type ImageInput = ArrayBuffer | Uint8Array;
type BaseOptions = {
    strict?: boolean;
    tolerance?: number;
    ignoreCaret?: boolean;
    ignoreAntialiasing?: boolean;
    antialiasingTolerance?: number;
    pixelRatio?: number;
    percentThreshold?: number;
};
type LooksSameOptions = BaseOptions;
type CreateDiffOptions = BaseOptions & {
    reference: ImageInput;
    current: ImageInput;
    highlightColor?: string;
};
type CompareResult = {
    equal: boolean;
    differentPixels?: number;
    totalPixels?: number;
};
declare const looksSameImpl: (reference: ImageInput, current: ImageInput, options?: LooksSameOptions) => Promise<CompareResult>;
declare const createDiff: ({ reference, current, highlightColor, ...options }: CreateDiffOptions) => Promise<Uint8Array<ArrayBufferLike>>;
type LooksSame = typeof looksSameImpl & {
    createDiff: typeof createDiff;
};
declare const looksSame: LooksSame;

export { looksSame as default };
